'use strict';
const fs = require('fs');

const path = process.argv[2];
if (!path) { console.error('usage: node extract.js <elf>'); process.exit(1); }
const buf = fs.readFileSync(path);

// ELF magic
if (!(buf[0] === 0x7f && buf[1] === 0x45 && buf[2] === 0x4c && buf[3] === 0x46)) {
  console.error('not an ELF file'); process.exit(1);
}
const is64 = buf[4] === 2;          // EI_CLASS
const le = buf[5] === 1;            // EI_DATA little-endian
if (!is64 || !le) { console.error('only little-endian ELF64 supported'); process.exit(1); }

// ELF64 header offsets
const e_phoff = Number(buf.readBigUInt64LE(0x20));
const e_phentsize = buf.readUInt16LE(0x36);
const e_phnum = buf.readUInt16LE(0x38);

const PT_LOAD = 1;
const out = {};

for (let i = 0; i < e_phnum; i++) {
  const off = e_phoff + i * e_phentsize;
  const p_type = buf.readUInt32LE(off + 0x00);
  if (p_type !== PT_LOAD) continue;
  const p_offset = Number(buf.readBigUInt64LE(off + 0x08));
  const p_vaddr = Number(buf.readBigUInt64LE(off + 0x10));
  const p_filesz = Number(buf.readBigUInt64LE(off + 0x20));

  // Only file-backed bytes have deterministic values; iterate 4-byte words.
  const words = Math.floor(p_filesz / 4);
  for (let w = 0; w < words; w++) {
    const fpos = p_offset + w * 4;
    if (fpos + 4 > buf.length) break;
    const addr = p_vaddr + w * 4;
    out[addr] = buf.readUInt32LE(fpos);
  }
}

process.stdout.write(JSON.stringify(out));
